14	/**
15	 * Once the sheet's today is set: with grace days on, closes every open period whose to-date plus the grace days is
16	 * before the new today, in order of their to-dates, as a close by hand would — whoever set the today, the sheet's
17	 * close permission governs only a close by hand — each writing PERIOD_CLOSED with auto=yes.
18	 */
19	public class AutoClosePeriods {
20	    public void close(@Val SheetResponse sheet, @Val LocalDate today, @Val ChangedBy by, PeriodRepository repository,
21	            RoleRepository roles, SettingRepository settings, Rollup rollup, Audit audit) {
22	        Integer grace = settings.graceDays(sheet.id());
23	        if (grace == null) {
24	            return;
25	        }
26	        for (Period period : repository.list(sheet.id()).stream()
27	                .filter(p -> !p.closed() && p.to().plusDays(grace).isBefore(today))
28	                .sorted(Comparator.comparing(Period::to).thenComparing(Period::id)).toList()) {
29	            Period closed = ClosePeriod.fix(period, repository, rollup);
30	            if (closed != null) {
31	                audit.record(RecordPeriodClosed.line(closed, by) + " auto=yes");
32	            }
33	        }
34	    }
35	}
