98	/** Closes the period (by a role the sheet's close permission gives), fixing its due-total and each person's as they are now; refuses a period already closed. */
99	public class ClosePeriod {
100	    public void close(@Val Period period, @Val ChangedBy by, PeriodRepository repository, RoleRepository roles,
101	            SettingRepository settings, Rollup rollup, Out<ClosedPeriod> closed) throws BadRequestException {
102	        String role = roles.roleOf(period.sheetId(), by.name());
103	        if (!settings.allows(period.sheetId(), "close", role)) {
104	            throw new BadRequestException("A " + role + " may not close a period on this sheet");
105	        }
106	        if (period.closed()) {
107	            throw new BadRequestException("That period is already closed");
108	        }
109	        Period fixed = fix(period, repository, rollup);
110	        if (fixed == null) {
111	            throw new BadRequestException("The period was closed by someone else; reload the sheet");
112	        }
113	        closed.set(new ClosedPeriod(fixed));
114	    }
115	
116	    /** Closes the open period, fixing its due-total and each person's as they are now; null when someone else closed it first. */
117	    static Period fix(Period period, PeriodRepository repository, Rollup rollup) {
118	        Map<Long, BigDecimal> personTotals = rollup.dueBetweenByPerson(period.sheetId(), period.from(), period.to());
119	        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
120	        if (!repository.close(period.id(), total, personTotals)) {
121	            return null;
122	        }
123	        return new Period(period.id(), period.sheetId(), period.name(), period.from(), period.to(), true, total,
124	                personTotals);
125	    }
126	}
