146	/**
147	 * Refuses a to-date before the from-date (blank: the sheet's today). Otherwise adds a period per calendar month from
148	 * the from-date's month to the to-date's, first to last day, named yyyy-mm, each recorded as PERIOD_ADDED; a month
149	 * whose name is in use on the sheet or whose days overlap a period is left out.
150	 */
151	public class GeneratePeriods {
152	    public void generate(@Val SheetResponse sheet, @Val GenerateRange range, @Val ChangedBy by,
153	            PeriodRepository repository, SheetRepository sheets, Audit audit, Out<GeneratePeriodsResponse> result) throws BadRequestException {
154	        LocalDate from = range.from() != null ? range.from() : sheets.today(sheet.id());
155	        if (range.to().isBefore(from)) {
156	            throw new BadRequestException("The to-date is on or after the from-date");
157	        }
158	        int made = 0;
159	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(range.to())); month = month
160	                .plusMonths(1)) {
161	            String name = month.toString();
162	            LocalDate first = month.atDay(1);
163	            LocalDate last = month.atEndOfMonth();
164	            if (repository.nameTaken(sheet.id(), name) || repository.overlaps(sheet.id(), first, last)) {
165	                continue;
166	            }
167	            new RecordPeriodAdded().record(repository.insert(sheet.id(), name, first, last), by, audit);
168	            made++;
169	        }
170	        result.set(new GeneratePeriodsResponse(made));
171	    }
172	}
